// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/** Scratch-only exact-bag characterization tests against the pre-repair baseline. */
class R2UnboundGraphEnumerationBaselineTest {

	private static final String NAMED_GRAPH_DATA = "<urn:g1> { <urn:a> <urn:p> <urn:o> } "
			+ "<urn:g2> { <urn:b> <urn:p> <urn:o> }";

	private SailRepository repository;

	@BeforeEach
	void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(new StringReader(NAMED_GRAPH_DATA), "urn:base:", RDFFormat.TRIG);
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void plainUnboundGraphVariableEnumeratesEveryNamedGraph() throws Exception {
		assertThat(query("SELECT ?g ?s { GRAPH ?g { ?s <urn:p> <urn:o> } }", Map.of()))
				.containsExactly("{g=urn:g1, s=urn:a}", "{g=urn:g2, s=urn:b}");
	}

	@Test
	void unboundOuterGraphContextReachesNestedSelect() throws Exception {
		assertThat(query("SELECT ?g ?seed ?x { GRAPH ?g { ?seed <urn:p> <urn:o> OPTIONAL { "
				+ "SELECT ?x { ?x <urn:p> <urn:o> } } } }", Map.of()))
						.containsExactly("{g=urn:g1, seed=urn:a, x=urn:a}", "{g=urn:g2, seed=urn:b, x=urn:b}");
	}

	@Test
	void nestedSameNamedLocalGraphDoesNotReplaceTheCallerGraph() throws Exception {
		assertThat(query("SELECT ?g ?seed ?x ?y { GRAPH ?g { ?seed <urn:p> <urn:o> OPTIONAL { "
				+ "SELECT ?x ?y { ?x <urn:p> <urn:o> GRAPH ?g { ?y <urn:p> <urn:o> } } } } }", Map.of()))
						.containsExactly("{g=urn:g1, seed=urn:a, x=urn:a, y=urn:a}",
								"{g=urn:g1, seed=urn:a, x=urn:a, y=urn:b}",
								"{g=urn:g2, seed=urn:b, x=urn:b, y=urn:a}",
								"{g=urn:g2, seed=urn:b, x=urn:b, y=urn:b}");
	}

	@Test
	void emptyNestedOptionalRetainsOuterGraphRows() throws Exception {
		assertThat(query("SELECT ?g ?seed ?x { GRAPH ?g { ?seed <urn:p> <urn:o> OPTIONAL { "
				+ "SELECT ?x { GRAPH ?local { ?x <urn:missing> <urn:o> } } } } }", Map.of()))
						.containsExactly("{g=urn:g1, seed=urn:a}", "{g=urn:g2, seed=urn:b}");
	}

	@Test
	void suppliedGraphBindingRestrictsEnumeration() throws Exception {
		Map<String, Value> bindings = Map.of("g", SimpleValueFactory.getInstance().createIRI("urn:g2"));
		assertThat(query("SELECT ?g ?s { GRAPH ?g { ?s <urn:p> <urn:o> } }", bindings))
				.containsExactly("{g=urn:g2, s=urn:b}");
	}

	private List<String> query(String sparql, Map<String, Value> bindings) throws Exception {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			TupleQuery tupleQuery = connection.prepareTupleQuery(sparql);
			bindings.forEach(tupleQuery::setBinding);
			List<String> rows = new ArrayList<>();
			try (TupleQueryResult results = tupleQuery.evaluate()) {
				for (BindingSet result : results) {
					Map<String, String> row = new TreeMap<>();
					for (String name : result.getBindingNames()) {
						if (result.getValue(name) != null) {
							row.put(name, result.getValue(name).toString());
						}
					}
					rows.add(row.toString());
				}
			}
			rows.sort(null);
			return rows;
		}
	}
}
